import router from '@/router';
import { SearchItem } from '@/services/Api/SearchService';

interface BookUrlParams {
  language: string;
  bookSlug: string;
  categorySlug?: string;
  authorSlug?: string;
  letter?: string;
}

interface BookSectionUrlParams extends BookUrlParams {
  bookSectionSlug: string;
}

interface AuthorUrlParams {
  language: string;
  authorSlug: string;
}

interface SearchUrlParams {
  language: string;
  query: string;
  showAdvancedSearch?: boolean;
  showHelp?: boolean;
  inBookOnly?: boolean;
  searchInPoem?: boolean;
  exact?: boolean;
  considerDiacritics?: boolean;
  equalizeWriting?: boolean;
  bookSlug?: string;
  bookId?: number;
  bookSearch?: boolean;
  returnTo?: string;
}

export default class UrlBuilderService {
  static getBookUrl({ language, bookSlug, categorySlug, authorSlug }: BookUrlParams) {
    if (categorySlug) {
      return `/${language}/categories/${categorySlug}/${bookSlug}`;
    }
    if (authorSlug) {
      return `/${language}/authors/${authorSlug}/${bookSlug}`;
    }
    return `/${language}/books/${bookSlug}`;
  }

  static getBookSectionUrl({
    language,
    bookSlug,
    bookSectionSlug,
    categorySlug,
    authorSlug
  }: BookSectionUrlParams) {
    if (categorySlug) {
      return `/${language}/categories/${categorySlug}/${bookSlug}/${bookSectionSlug}`;
    }
    if (authorSlug) {
      return `/${language}/authors/${authorSlug}/${bookSlug}/${bookSectionSlug}`;
    }
    return `/${language}/books/${bookSlug}/${bookSectionSlug}`;
  }

  static getAuthorUrl({ language, authorSlug }: AuthorUrlParams) {
    return `/${language}/authors/${authorSlug}`;
  }

  static getSearchQueryUrl({ language, query, bookSlug, returnTo, ...rest }: SearchUrlParams) {
    const searchParams: { [key: string]: string } = { query };
    if (bookSlug) {
      searchParams.slug = bookSlug;
    }
    if (returnTo) {
      searchParams.returnTo = returnTo;
    }
    Object.entries(rest)
      .filter(([key, value]) => value)
      .forEach(([key, value]) => {
        searchParams[key] = Number(value).toString();
      });
    return `/${language}/search?${new URLSearchParams({ ...searchParams }).toString()}`;
  }

  static getSearchResultItemUrl(searchItem: SearchItem, index: number) {
    let url = '';
    if (searchItem.section_slug) {
      url = UrlBuilderService.getBookSectionUrl({
        language: router.currentRoute.params.language,
        bookSlug: searchItem.book_slug,
        bookSectionSlug: searchItem.section_slug
      });
    } else {
      url = UrlBuilderService.getBookUrl({
        language: router.currentRoute.params.language,
        bookSlug: searchItem.book_slug
      });
    }
    if (typeof router.currentRoute.query.query === 'string') {
      const searchParams = new URLSearchParams();
      Object.entries(router.currentRoute.query).forEach(([name, value]) => {
        if (name !== 'scope' && typeof value === 'string') {
          searchParams.set(name, value);
        }
      });
      searchParams.set('index', index.toString());
      searchParams.set('highlight', searchItem.highlight.join(','));
      return `${url}?${searchParams.toString()}`;
    }
    return url;
  }

  static getSearchParams({
    query,
    index,
    highlight = ''
  }: {
    query: string;
    index: number | string;
    highlight?: string;
  }) {
    return new URLSearchParams({ query, index: index.toString(), highlight });
  }
}
