









import Vue from 'vue';
import UrlBuilderService from '@/services/UrlBuilderService';
import Component from 'vue-class-component';
import { Prop } from 'vue-property-decorator';

interface Book {
  name: string;
  language: string;
  slug: string;
  url?: string;
  created_at: string;
}

@Component
export default class UserRecentBooks extends Vue {
  @Prop({ required: true })
  list!: Array<Book>;

  get books() {
    return this.list.map((book: Book) => ({
      url: UrlBuilderService.getBookUrl({ language: book.language, bookSlug: book.slug }),
      ...book
    }));
  }
}
