import { ActionTree, GetterTree, Module, MutationTree } from 'vuex';
import axios from 'axios';
import { RootState } from '@/store';
import {
  Author,
  Book,
  Books,
  BookSection,
  Category,
  ListType,
  NavigationData,
  NavigationDataFilter,
  NavigationDataRaw
} from '@/services/Navigation/types';
import HighlightService from '@/services/Navigation/HighlightService';
import ProcessService from '@/services/Navigation/ProcessService';
import PagingService from '@/services/Navigation/PagingService';
import NavigationService from '@/services/Api/NavigationService';
import CheckService from '@/services/Navigation/CheckService';
import ExpandService from '@/services/Navigation/ExpandService';
import { LIST_TYPE_DEFAULT } from '@/constants';
import ArrayService from '@/services/ArrayService';
import SearchScopeService from '@/services/SearchScopeService';

export type NavigationState = {
  language: string;
  loading: boolean;
  error: boolean;
  data: { [language: string]: NavigationData };
  showSearchResultsFlag: boolean;
  listType: ListType;
  filterQuery: string;
};

const initialData: NavigationData = {
  books: {}, // books must be an object with unique key to avoid duplicates
  booksAlphabet: [],
  categories: [],
  authors: [],
  authorsAlphabet: [],
  foundBooks: {},
  filter: {
    // filter data from search input in left column
    categoryIds: [],
    authorIds: [],
    bookSlugs: []
  }
};

const state: NavigationState = {
  // language variable is for Catalog.vue and Search.vue only
  // we can switch catalog navigation in Sidebar.vue to the other language without changing url (to avoid blank content-area when url will be "/ru" or "/en")
  // we initialize and watch it in Reader.vue so it will be synced with url (plus decide should we show Catalog.vue or NewBooks.vue)
  // we don't know the exact language while user is on the main page, so it's empty by default
  language: '',
  loading: false,
  error: false,
  data: {
    ru: initialData,
    en: initialData,
    st: initialData
  },
  showSearchResultsFlag: false,
  listType: LIST_TYPE_DEFAULT,
  filterQuery: ''
};

const actions: ActionTree<NavigationState, RootState> = {
  async fetch({ commit, state }, language) {
    // get navigation from backend

    commit('setLoading', true);
    commit('setError', false);
    return NavigationService.getNavigation(language)
      .then((navigationDataRaw: NavigationDataRaw) => {
        // process navigation data
        let navigationData = ProcessService.processNavigation(navigationDataRaw);
        // highlight navigation items
        navigationData = HighlightService.actualizeHighlight(
          {
            ...state.data[state.language],
            ...navigationData
          },
          state.listType,
          state.filterQuery
        );
        // store it in the state
        commit('updateNavigationData', navigationData);
      })
      .catch(e => {
        if (!axios.isCancel(e)) {
          // if request was canceled - we should not consider this as error
          console.error(e); // eslint-disable-line no-console
          commit('setError', e);
        }
      })
      .finally(() => {
        if (NavigationService.callsCount === 0) {
          commit('setLoading', false);
        }
      });
  },

  async fetchCategoryBooks({ commit, state }, { language, categoryId }) {
    const { books: newBooks } = await NavigationService.getCategoryBooks(language, categoryId);
    const processedBooks = ProcessService.processBooks(newBooks);
    let navigationData = {
      ...state.data[state.language],
      books: ProcessService.concatBooks(state.data[state.language].books, processedBooks),
      categories: ProcessService.mapBookIds(state.data[state.language].categories, categoryId, processedBooks)
    };
    if (HighlightService.needBookHighlight(navigationData, state.listType, state.filterQuery)) {
      navigationData.books = HighlightService.highlightBook(navigationData.books);
    }
    commit('updateNavigationData', navigationData);
  },

  async fetchCategoriesBooks({ commit, state }, { language, categoryIds }) {
    const { books: newBooks, categories: categoryBookIds } = await NavigationService.getCategoriesBooks(
      language,
      categoryIds
    );
    const processedBooks = ProcessService.processBooks(newBooks);
    const categories = SearchScopeService.applyCategoryBookMappings(
      state.data[state.language].categories,
      categoryIds,
      categoryBookIds
    );
    commit('updateNavigationData', {
      ...state.data[state.language],
      books: ProcessService.concatBooks(state.data[state.language].books, processedBooks),
      categories
    });
  },

  async toggleCategorySelection({ commit, dispatch, state }, categoryId: number) {
    const data = state.data[state.language];
    const category = data.categories.find(item => item.id === categoryId);
    if (!category) {
      return;
    }
    const shouldLoadBookIds = !category.checked;
    commit('toggleCategoryCheck', categoryId);
    if (shouldLoadBookIds) {
      const unloadedCategoryIds = SearchScopeService.getUnloadedBookCategoryIds(data.categories, categoryId);
      if (unloadedCategoryIds.length) {
        await dispatch('fetchCategoriesBooks', {
          language: state.language,
          categoryIds: unloadedCategoryIds
        }).catch(() => {
          // Category selection remains usable if the optional count hydration fails.
        });
      }
    }
  },

  async fetchAuthorBooks({ commit, state }, { language, authorId }) {
    const { books: newBooks } = await NavigationService.getAuthorBooks(language, authorId);
    const processedBooks = ProcessService.processBooks(newBooks);
    let navigationData = {
      ...state.data[state.language],
      books: ProcessService.concatBooks(state.data[state.language].books, processedBooks),
      authors: ProcessService.mapBookIds(state.data[state.language].authors, authorId, processedBooks)
    };
    if (HighlightService.needBookHighlight(navigationData, state.listType, state.filterQuery)) {
      navigationData.books = HighlightService.highlightBook(navigationData.books);
    }
    commit('updateNavigationData', navigationData);
  },

  async fetchLetterBooks({ commit, state }, { language, letterName }) {
    const { books: newBooks } = await NavigationService.getLetterBooks(language, letterName);
    const processedBooks = ProcessService.processBooks(newBooks);
    let navigationData = {
      ...state.data[state.language],
      books: ProcessService.concatBooks(state.data[state.language].books, processedBooks)
    };
    const letter = state.data[state.language].booksAlphabet.find(one => one.name === letterName);
    if (letter) {
      navigationData.booksAlphabet = ProcessService.mapBookIds(
        state.data[state.language].booksAlphabet,
        letter.id,
        processedBooks
      );
    }
    if (HighlightService.needBookHighlight(navigationData, state.listType, state.filterQuery)) {
      navigationData.books = HighlightService.highlightBook(navigationData.books);
    }
    commit('updateNavigationData', navigationData);
  },

  async fetchBookSections({ commit, state }, { language, bookSlug }) {
    const { is_show_edit_link, edit_link, bookSections } = await NavigationService.getBookSections(
      language,
      bookSlug
    );
    let navigationData = { ...state.data[state.language] };
    navigationData.books[bookSlug].children = ProcessService.processBookSections(
      bookSections,
      navigationData.books[bookSlug]
    );
    navigationData.books[bookSlug].edit_link = edit_link;
    navigationData.books[bookSlug].is_show_edit_link = is_show_edit_link;
    if (HighlightService.needBookSectionHighlight(navigationData.books)) {
      navigationData.books = HighlightService.highlightBookSection(navigationData.books);
    }
    commit('updateNavigationData', navigationData);
  },

  async highlightLetterByBookSlug({ commit, dispatch, state }, { language, bookSlug }) {
    try {
      const bookParams = await NavigationService.getBookParams(language, bookSlug);
      const navigationData = state.data[state.language];
      const { booksAlphabet } = navigationData;
      const letter = booksAlphabet.find(one => one.name === bookParams.letter);
      if (!letter) {
        throw new Error(`Book letter not found: ${bookParams.letter}`);
      }

      letter.expanded = true;
      letter.highlight = true;
      commit('updateNavigationData', { booksAlphabet });

      // A direct URL is opened before NavLetter/NavBook components exist. Load
      // the complete branch here instead of relying on component watchers.
      if (!state.data[state.language].books[bookSlug]) {
        await dispatch('fetchLetterBooks', { language, letterName: letter.name });
      }
      const book = state.data[state.language].books[bookSlug];
      if (!book) {
        throw new Error(`Book not found in letter ${letter.name}: ${bookSlug}`);
      }
      book.expanded = true;
      book.highlight = true;
      commit('updateNavigationData', { books: state.data[state.language].books });

      if (!book.children.length) {
        await dispatch('fetchBookSections', { language, bookSlug });
      }
      commit('actualizeHighlight');
    } catch (e) {
      if (!axios.isCancel(e)) {
        console.error(e); // eslint-disable-line no-console
        commit('setError', e);
      }
    }
  },

  /**
   * Filter categories
   */
  async filter({ commit, state }, { language, query }) {
    let filterData: {
      books?: Array<Book>;
      categories?: Array<number>;
      bookSections?: Array<string>;
      authors?: Array<number>;
      letters?: Array<string>;
    } = {};
    const stateData = state.data[state.language];
    let filter: NavigationDataFilter = stateData.filter;
    let stateBooks: Books = { ...stateData.books };
    let filteredAuthors;
    switch (state.listType) {
      case 'categories':
        filterData = await NavigationService.filterCategories(language, query);
        break;
      case 'authors':
        filterData = await NavigationService.filterAuthors(language, query);
        filteredAuthors = stateData.authors.filter(
          author => filterData.authors && filterData.authors.includes(author.id)
        );
        break;
      case 'books':
        filterData = await NavigationService.filterLetters(language, query);
        break;
    }

    filter.categoryIds = filterData.categories || [];
    filter.authorIds = filterData.authors || [];
    filter.bookSlugs = [];
    if (filterData.books) {
      filter.bookSlugs = filterData.books.map(book => book.slug);
      stateBooks = { ...stateBooks, ...ProcessService.processBooks(filterData.books) };
    }

    commit('updateNavigationData', { filter, books: stateBooks });
  },

  /**
   * Search books if there is a global search query
   */
  async searchBooks({ commit, getters, rootState }, { language, query, ...rest }) {
    commit('setLoading', true);
    commit('search/setError', false, { root: true });
    if (rootState.search.advancedSearch && !getters.hasCheckedEntities) {
      // if there is advanced search and there are no checked checkboxes - return empty list
      commit('updateNavigationData', { foundBooks: [] });
      commit('setLoading', false);
    } else {
      return NavigationService.searchBooks(language, query, rest)
        .then(books => {
          // store it in the state
          commit('updateNavigationData', {
            foundBooks: ProcessService.processBooks(books, { checked: true })
          });
        })
        .catch(e => {
          if (!axios.isCancel(e)) {
            // A sidebar-search failure must not replace an already loaded catalog.
            commit('search/setError', true, { root: true });
          }
        })
        .finally(() => {
          if (NavigationService.callsCount === 0) {
            commit('setLoading', false);
          }
        });
    }
  },

  /**
   *  Search books sections if there is a global search query
   */
  async searchBookSections({ commit, state }, { language, query, bookSlug, ...rest }) {
    const bookSections = await NavigationService.searchBookSections(language, query, bookSlug, rest);
    const bookSectionEntries = await NavigationService.searchBookSectionEntries(
      language,
      query,
      bookSlug,
      rest
    );
    const book = state.data[state.language].foundBooks[bookSlug];
    state.data[state.language].foundBooks[bookSlug].children = ProcessService.processBookSections(
      bookSections,
      book,
      { checked: true },
      bookSectionEntries
    );
    commit('updateNavigationData', state.data[state.language]);
  }
};

const mutations: MutationTree<NavigationState> = {
  updateNavigationData(state: NavigationState, navigationData: NavigationData) {
    state.data[state.language] = { ...state.data[state.language], ...navigationData };
  },
  setLanguage(state: NavigationState, language: string) {
    state.language = language;
  },
  setLoading(state: NavigationState, loading: boolean) {
    state.loading = loading;
  },
  setError(state: NavigationState, error: boolean) {
    state.error = error;
  },
  actualizeHighlight(state: NavigationState) {
    state.data[state.language] = HighlightService.actualizeHighlight(
      state.data[state.language],
      state.listType,
      state.filterQuery
    );
  },
  toggleCategoryExpand(state: NavigationState, categoryId: number) {
    ExpandService.toggleCategoryExpand(state.data[state.language].categories, categoryId);
  },
  toggleAuthorExpand(state: NavigationState, authorId: number) {
    ExpandService.toggleAuthorExpand(state.data[state.language].authors, authorId);
  },
  toggleBookExpand(state: NavigationState, bookSlug: string) {
    ExpandService.toggleBookExpand(state.data[state.language].books, bookSlug);
  },
  toggleFoundBookExpand(state: NavigationState, bookSlug: string) {
    ExpandService.toggleBookExpand(state.data[state.language].foundBooks, bookSlug);
  },
  toggleBookSectionExpand(
    state: NavigationState,
    {
      bookSectionId,
      bookSlug,
      catalogTree
    }: { bookSectionId: string; bookSlug: string; catalogTree?: boolean }
  ) {
    if (state.showSearchResultsFlag && !catalogTree) {
      ExpandService.toggleFoundBookSectionExpand(
        state.data[state.language].foundBooks,
        bookSectionId,
        bookSlug
      );
    } else {
      ExpandService.toggleBookSectionExpand(state.data[state.language].books, bookSectionId, bookSlug);
    }
  },
  toggleBookLetterExpand(state: NavigationState, letterId: number) {
    ExpandService.toggleLetterExpand(state.data[state.language].booksAlphabet, letterId);
  },
  toggleAuthorLetterExpand(state: NavigationState, letterId: number) {
    ExpandService.toggleLetterExpand(state.data[state.language].authorsAlphabet, letterId);
  },
  collapseAll(state: NavigationState) {
    state.data[state.language] = {
      ...state.data[state.language],
      ...ProcessService.collapseAll(state.data[state.language])
    };
  },
  collapseBookTree(state: NavigationState, bookSlug: string) {
    const collapseSections = (sections: Array<BookSection>) => {
      sections.forEach(section => {
        section.expanded = false;
        collapseSections(section.children || []);
      });
    };
    const collapseBook = (books: Books) => {
      const book = books[bookSlug];
      if (!book) {
        return;
      }
      book.expanded = false;
      collapseSections(book.children || []);
    };
    collapseBook(state.data[state.language].books);
    collapseBook(state.data[state.language].foundBooks);
  },
  restoreExpansionState(state: NavigationState, snapshot) {
    const data = state.data[state.language];
    const categoryIds = new Set(snapshot.categories || []);
    const authorIds = new Set(snapshot.authors || []);
    const bookLetterIds = new Set(snapshot.bookLetters || []);
    const authorLetterIds = new Set(snapshot.authorLetters || []);
    const bookSlugs = new Set(snapshot.books || []);
    const foundBookSlugs = new Set(snapshot.foundBooks || []);
    const sectionKeys = new Set(snapshot.sections || []);
    const applySections = (sections: Array<BookSection>, bookSlug: string) => {
      sections.forEach(section => {
        section.expanded = sectionKeys.has(`${bookSlug}:${section.id}`);
        applySections(section.children || [], bookSlug);
      });
    };
    data.categories.forEach(category => {
      category.expanded = categoryIds.has(category.id);
    });
    data.authors.forEach(author => {
      author.expanded = authorIds.has(author.id);
    });
    data.booksAlphabet.forEach(letter => {
      letter.expanded = bookLetterIds.has(letter.id);
    });
    data.authorsAlphabet.forEach(letter => {
      letter.expanded = authorLetterIds.has(letter.id);
    });
    Object.values(data.books).forEach(book => {
      book.expanded = bookSlugs.has(book.slug);
      applySections(book.children || [], book.slug);
    });
    Object.values(data.foundBooks).forEach(book => {
      book.expanded = foundBookSlugs.has(book.slug);
      applySections(book.children || [], book.slug);
    });
  },
  toggleCategoryCheck(state: NavigationState, categoryId: number) {
    CheckService.toggleCategoryCheck(state.data[state.language], categoryId);
  },
  toggleBookCheck(state: NavigationState, bookSlug: string) {
    CheckService.toggleBookCheck(state.data[state.language], bookSlug);
  },
  toggleFoundBookCheck(state: NavigationState, bookSlug: string) {
    CheckService.toggleFoundBookCheck(state.data[state.language], bookSlug);
  },
  toggleBookSectionCheck(state: NavigationState, { bookSectionId, bookSlug }) {
    CheckService.toggleBookSectionCheck(state.data[state.language], bookSectionId, bookSlug);
  },
  toggleFoundBookSectionCheck(state: NavigationState, { bookSectionId, bookSlug }) {
    CheckService.toggleFoundBookSectionCheck(state.data[state.language], bookSectionId, bookSlug);
  },
  checkAll(state: NavigationState) {
    state.data[state.language] = CheckService.checkAll(state.data[state.language]);
  },
  uncheckAll(state: NavigationState) {
    state.data[state.language] = CheckService.uncheckAll(state.data[state.language]);
  },
  updatePreloadFlag(state: NavigationState) {
    // this method will DO the mutation of data
    ProcessService.updatePreloadFlag(state.data[state.language].books);
  },
  setShowSearchResultsFlag(state: NavigationState, showSearchResultsFlag) {
    state.showSearchResultsFlag = showSearchResultsFlag;
    if (!showSearchResultsFlag && state.language) {
      // clear found books if we switch back to catalog
      state.data[state.language].foundBooks = {};
    }
  },
  setListType(state: NavigationState, listType: ListType) {
    state.listType = listType;
  },
  clearFoundBooks(state) {
    state.data[state.language].foundBooks = {};
  },
  resetFilter(state) {
    state.data[state.language].filter = { ...initialData.filter };
  },
  updateFilterQuery(state, filterQuery) {
    state.filterQuery = filterQuery;
  }
};

const getters: GetterTree<NavigationState, RootState> = {
  dataFromStateLanguage: (state: NavigationState) => {
    // this getters is used when user clicks on different languages in the left sidebar and the url is not changing (just to show the catalog tree for selected language)
    return !!state.language && state.data[state.language];
  },
  dataFromRouteLanguage: (state: NavigationState, getters, rootState) => {
    // this getter is used to get current book / bookSection / category from slugs in url
    const routeLanguage = rootState.route.params.language;
    return !!routeLanguage && state.data[routeLanguage];
  },
  currentBook: (state: NavigationState, getters, rootState) => {
    const routeLanguage = rootState.route.params.language;
    const routeBook = rootState.route.params.book;
    if (!(routeLanguage && routeBook)) {
      return undefined;
    }
    const data = getters.dataFromRouteLanguage;
    const books: Array<Book> = data ? Object.values(data.books) : [];
    return books.find(book => book.language === routeLanguage && book.slug === routeBook);
  },
  currentBookSections: (state: NavigationState, getters) => {
    const book = getters.currentBook;
    if (!book) {
      return undefined;
    }
    return book.children;
  },
  currentBookSection: (state: NavigationState, getters, rootState) => {
    const routeLanguage = rootState.route.params.language;
    const routeBook = rootState.route.params.book;
    const routeBookSection = rootState.route.params.bookSection;
    const book = getters.currentBook;
    if (!book) {
      return undefined;
    }
    const bookSections: Array<BookSection> = book.children;

    if (book && book.is_article) {
      // when book has only one article - there is no info in the left col, so we fake the object
      return {
        id: routeBookSection,
        code: routeBookSection,
        slug: routeBookSection,
        bookId: book.id,
        book: book,
        number_code_chapter: null,
        number_code_section: null,
        number_code_poem: null,
        is_parent: false,
        depth: 1,
        preload: false,
        number: 0, // number in the book
        index: 0
      } as BookSection;
    }

    return bookSections.find(
      one =>
        one.book.language === routeLanguage && one.book.slug === routeBook && one.slug === routeBookSection
    );
  },
  pagination: (state: NavigationState, getters) => {
    return PagingService.getPaging(getters.currentBookSections, getters.currentBookSection);
  },
  checkedCategories: (state: NavigationState, getters) => {
    const data = getters.dataFromRouteLanguage;
    const categories: Array<Category> = data ? data.categories : [];
    return categories.filter(category => category.checked && !category.partiallyChecked);
  },
  checkedBooks: (state: NavigationState, getters) => {
    const data = getters.dataFromRouteLanguage as NavigationData;
    if (!data) {
      return [];
    }
    const checkedCategoriesIds = getters.checkedCategories.map((category: Category) => category.id);
    return Object.values(data.books).filter(
      book =>
        book.checked &&
        !book.partiallyChecked &&
        !(book.categories && ArrayService.hasIntersections(book.categories, checkedCategoriesIds)) // ... and if book's category IDs are not in checked categories IDs
    );
  },
  selectedBooksCount: (state: NavigationState, getters) => {
    return SearchScopeService.getSelectedBookIds(
      getters.checkedBooks as Array<Book>,
      getters.checkedCategories as Array<Category>
    ).size;
  },
  checkedBookSections: (state: NavigationState, getters) => {
    const data = getters.dataFromRouteLanguage as NavigationData;
    if (!data) {
      return [];
    }
    let checkedBookIds = getters.checkedBooks.map((book: Book) => book.id);
    getters.checkedCategories.forEach((category: Category) => {
      checkedBookIds = checkedBookIds.concat(category.bookIds);
    });
    const checkedBookSections: Array<BookSection> = [];
    for (let slug in data.books) {
      if (!data.books.hasOwnProperty(slug)) {
        continue;
      }
      data.books[slug].children.forEach(bookSection => {
        if (
          bookSection.checked &&
          !bookSection.partiallyChecked &&
          !checkedBookIds.includes(bookSection.book.id)
        ) {
          checkedBookSections.push(bookSection);
        }
      });
    }
    return checkedBookSections;
  },
  checkedFoundBooks: (state: NavigationState, getters) => {
    const data = getters.dataFromRouteLanguage as NavigationData;
    if (!(data && data.foundBooks)) {
      return [];
    }
    return Object.values(data.foundBooks).filter(book => book.checked && !book.partiallyChecked);
  },
  checkedFoundBookSections: (state: NavigationState, getters) => {
    const data = getters.dataFromRouteLanguage as NavigationData;
    if (!(data && data.foundBooks)) {
      return [];
    }
    let bookSections: Array<BookSection> = [];
    Object.values(data.foundBooks)
      .filter(book => !book.checked)
      .forEach(book => {
        bookSections = bookSections.concat(book.children.filter(bookSection => bookSection.checked));
      });
    return bookSections;
  },
  hasCheckedEntities(state: NavigationState, getters) {
    const books = getters.checkedBooks as Array<Book>;
    const categories = getters.checkedCategories as Array<Category>;
    const bookSections = getters.checkedBookSections as Array<BookSection>;
    const foundBooks = getters.checkedFoundBooks as Array<Book>;
    const foundBookSections = getters.checkedFoundBookSections as Array<BookSection>;

    return (
      !!books.length ||
      !!bookSections.length ||
      !!categories.length ||
      !!foundBooks.length ||
      !!foundBookSections.length
    );
  },

  showSearchResults: (state: NavigationState, getters, rootState) => {
    return state.showSearchResultsFlag && rootState.route.name === 'search-results';
  }
};

export const module = {
  namespaced: true,
  state,
  actions,
  mutations,
  getters
} as Module<NavigationState, RootState>;
