

















import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop } from 'vue-property-decorator';

@Component
export default class NewsList extends Vue {
  @Prop({ required: true })
  news!: Array<any>;

  @Prop({ required: true })
  pagination!: Array<any>;

  getNews() {
    const news: { [key: string]: any } = {};
    this.news.forEach((item: any) => {
      const activeFrom = item['active_from']; // eslint-disable-line dot-notation
      news[activeFrom] = news[activeFrom] || [];
      news[activeFrom].push(item);
    });
    return news;
  }
}
