

























































































































import Vue from 'vue';
import { Action, Getter, Mutation, State } from 'vuex-class';
import Component from 'vue-class-component';
import { Prop } from 'vue-property-decorator';
import IconLogout from '@/assets/icons/logout.svg';
import { UserState } from '@/store/modules/user';
import Overlay from '@/components/ui/Overlay.vue';
import Profile from '@/components/Profile.vue';
import IconArrowDown from '@/assets/icons/arrow-down.svg';
import IconBook from '@/assets/icons/book.svg';
import IconTextSettings from '@/assets/icons/text-settings-icon.svg';
import IconReturn from '@/assets/icons/return.svg';
import IconList from '@/assets/icons/list.svg';
import IconSearch from '@/assets/icons/zoom.svg';
import IconBookmark from '@/assets/icons/bookmark-nav.svg';
import IconMore from '@/assets/icons/more.svg';
import { getTranslation } from '@/services/Translation';
import { Book, BookSection } from '@/services/Navigation/types';
import { LANGUAGE_CODE_DEFAULT } from '@/constants';

@Component({
  components: {
    Profile,
    Overlay,
    IconLogout,
    IconBook,
    IconList,
    IconSearch,
    IconBookmark,
    IconMore,
    IconReturn,
    IconTextSettings,
    IconArrowDown
  }
})
export default class Header extends Vue {
  loading: boolean = false;

  getTranslation = getTranslation;

  @Prop({ required: false, default: false })
  mobileReader!: boolean;

  @Getter('currentBook', { namespace: 'navigation' })
  currentBook?: Book;

  @Getter('currentBookSection', { namespace: 'navigation' })
  currentBookSection?: BookSection;

  @Action('logout', { namespace: 'auth' })
  sendLogout!: Function;

  @State('user')
  user!: UserState;

  @State('language', { namespace: 'navigation' })
  navLanguage!: string;

  @Mutation('setReadMode', { namespace: 'reader' })
  setReadMode!: Function;

  @Mutation('setLanguage', { namespace: 'navigation' })
  setLanguage!: Function;

  @Mutation('toggleTextTypesFilter', { namespace: 'reader' })
  toggleTextTypesFilter!: Function;

  showProfileOverlay: boolean = false;

  showLogoutOverlay: boolean = false;

  mobileActionsVisible: boolean = false;

  get readerBook() {
    return this.currentBook || (this.currentBookSection && this.currentBookSection.book);
  }

  get compactViewport() {
    return typeof window !== 'undefined' && window.innerWidth <= 1024;
  }

  get homeUrl() {
    if (!this.compactViewport) {
      return '/';
    }
    const language = this.$route.params.language || this.navLanguage || LANGUAGE_CODE_DEFAULT;
    return `/${language}/library`;
  }

  onLogoClick() {
    this.setReadMode(false);
    if (this.compactViewport) {
      this.setLanguage(this.$route.params.language || this.navLanguage || LANGUAGE_CODE_DEFAULT);
    } else {
      this.setLanguage('');
    }
  }

  async logout() {
    try {
      await this.sendLogout();
      this.$router.push('/login').catch(() => {});
    } catch (e) {
      // do nothing
    }
  }

  leaveMobileReader() {
    this.setReadMode(false);
    if (typeof this.$route.query.query === 'string' && this.$route.query.query) {
      const query = { ...this.$route.query };
      delete query.index;
      delete query.highlight;
      delete query.reading;
      const searchParams = new URLSearchParams();
      Object.entries(query).forEach(([name, value]) => {
        if (typeof value === 'string') {
          searchParams.set(name, value);
        }
      });
      this.$router.push(`/${this.$route.params.language}/search?${searchParams.toString()}`).catch(() => {});
      return;
    }
    const path = this.$route.path
      .split('/')
      .slice(0, -1)
      .join('/');
    this.$router.push(path || '/').catch(() => {});
  }

  toggleTextSettings() {
    this.$emit('toggle-text-settings');
    this.toggleTextTypesFilter();
  }

  openBookmarks() {
    this.mobileActionsVisible = false;
    this.$emit('toggle-bookmarks');
  }

  openThemePicker() {
    this.mobileActionsVisible = false;
    this.$emit('toggle-theme');
  }

  openTextSettings() {
    this.mobileActionsVisible = false;
    this.toggleTextSettings();
  }
}
