











































import Vue from 'vue';
import AuthLayout from '@/layouts/AuthLayout.vue';
import Component from 'vue-class-component';
import { getTranslation } from '@/services/Translation';
import AuthService from '@/services/Api/AuthService';
import Login from '@/views/Login.vue';
import LoginForm from '@/components/LoginForm.vue';
import { Action, State } from 'vuex-class';
import Loader from '@/components/ui/Loader.vue';
import { User } from '@/store/modules/user';
import UserService from '@/services/Api/UserService';
import { store } from '@/store';
import { Watch } from 'vue-property-decorator';

@Component({
  components: { Loader, LoginForm, Login, AuthLayout }
})
export default class VerifyEmail extends Vue {
  loading = true;
  fail = false;
  resendingVerification = false;
  verificationResent = false;
  needPageReload = false;

  @State('authorized', { namespace: 'auth' })
  authorized!: boolean;

  @State('data', { namespace: 'user' })
  user!: User;

  @Action('logout', { namespace: 'auth' })
  sendLogout!: Function;

  getTranslation = getTranslation;

  async mounted() {
    if (this.$route.name === 'verify-email') {
      await this.verifyEmail();
    }
    this.loading = false;
  }

  @Watch('authorized')
  async onAuthorizedChange() {
    this.loading = true;
    await this.verifyEmail();
    this.loading = false;
  }

  async verifyEmail() {
    const userId = this.$route.params.userId;
    const hash = this.$route.params.hash;
    const expires = this.$route.query.expires || '';
    const signature = this.$route.query.signature || '';

    if (
      !(userId && hash && typeof expires == 'string' && typeof signature === 'string' && expires && signature)
    ) {
      this.fail = true;
      return;
    }
    const result = await AuthService.verifyEmail(userId, hash, expires, signature).catch(async e => {
      if (e.response.status === 429) {
        this.needPageReload = true;
      }
      if (e.response.status === 401) {
        await this.sendLogout();
      }
      this.fail = true;
    });
    if (result && result.data && result.data.success) {
      await this.$router.replace('/');
      return;
    } else {
      this.fail = true;
    }
  }

  async resendVerification() {
    this.resendingVerification = true;
    try {
      await AuthService.verifyEmailResend();
      this.fail = false;
      this.resendingVerification = false;
      this.verificationResent = true;
    } catch {
      this.fail = true;
    }
  }

  reloadPage() {
    window.location.reload();
  }

  async logout() {
    this.sendLogout();
    await this.$router.replace('/');
  }
}
