import { BookSection, PagingItem } from '@/services/Navigation/types';

export default class PagingService {
  private static instance: PagingService;

  private static getInstance() {
    if (!PagingService.instance) {
      PagingService.instance = new PagingService();
    }
    return PagingService.instance;
  }

  public static getPaging(bookSections: Array<BookSection>, currentSection: BookSection | null) {
    if (!currentSection) {
      return null;
    }
    const instance = PagingService.getInstance();
    return {
      chapter: currentSection.number_code_chapter,
      poem: currentSection.number_code_poem,
      section: currentSection.number_code_section,
      chapters: Object.values(instance.getChapters(bookSections)),
      sections: Object.values(instance.getSections(bookSections, currentSection)),
      poems: Object.values(instance.getPoems(bookSections, currentSection))
    };
  }

  private getChapters(bookSections: Array<BookSection>) {
    const chapters: { [key: number]: PagingItem } = {};
    bookSections
      .filter(({ number_code_chapter }) => number_code_chapter !== null)
      .forEach(({ number_code_chapter: number, slug }) => {
        if (!chapters[number as number]) {
          chapters[number as number] = { number, bookSectionSlug: slug };
        }
      });
    return chapters;
  }

  private getSections(bookSections: Array<BookSection>, currentSection: BookSection) {
    const sections: { [key: number]: PagingItem } = {};
    bookSections
      .filter(
        bookSection =>
          !!bookSection.number_code_section &&
          (!currentSection.number_code_chapter ||
            currentSection.number_code_chapter === bookSection.number_code_chapter)
      )
      .forEach(({ number_code_section: number, slug }) => {
        if (!sections[number as number]) {
          sections[number as number] = { number, bookSectionSlug: slug };
        }
      });
    return sections;
  }

  private getPoems(bookSections: Array<BookSection>, currentSection: BookSection) {
    const poems: { [key: number]: PagingItem } = {};
    bookSections
      .filter(
        bookSection =>
          !!bookSection.number_code_poem &&
          (!currentSection.number_code_chapter ||
            currentSection.number_code_chapter === bookSection.number_code_chapter) &&
          (!currentSection.number_code_section ||
            currentSection.number_code_section === bookSection.number_code_section)
      )
      .forEach(({ number_code_poem: number, slug }) => {
        poems[number as number] = { number, bookSectionSlug: slug };
      });
    return poems;
  }
}
