import { store } from '@/store';
import { ApiService } from '@/services/Api/ApiService';
import { endpoints } from '@/api-endpoints.json';
import { NavigationDataRaw } from '../../Navigation/types';
import { SearchBaseOptions } from '@/services/Api/SearchService';

export default class NavigationService {
  private static instance: NavigationService;

  private apiService: ApiService = new ApiService();

  private static getInstance() {
    if (!NavigationService.instance) {
      NavigationService.instance = new NavigationService();
    }
    return NavigationService.instance;
  }

  static get callsCount() {
    return this.getInstance().apiService.callsCount;
  }

  static async getNavigation(lang: string): Promise<NavigationDataRaw> {
    const instance = this.getInstance();
    return instance.apiService
      .setEndpoint(endpoints.navigation.catalog.replace(':lang', lang))
      .setToken(store.state.auth.token)
      .get()
      .then(response => response.data.data);
  }

  static async getCategoryBooks(lang: string, categoryId: number) {
    const instance = this.getInstance();
    const endpoint = endpoints.navigation.categoryBooks
      .replace(':lang', lang)
      .replace(':id', categoryId.toString());
    return instance.apiService
      .setEndpoint(endpoint)
      .setToken(store.state.auth.token)
      .get()
      .then(response => response.data.data);
  }

  static async getCategoriesBooks(lang: string, categoryIds: Array<number>) {
    const instance = this.getInstance();
    return instance.apiService
      .setEndpoint(endpoints.navigation.booksByCategories.replace(':lang', lang))
      .setToken(store.state.auth.token)
      .setBody({ categories: categoryIds })
      .post()
      .then(response => response.data.data);
  }

  static async getAuthorBooks(lang: string, authorId: number) {
    const instance = this.getInstance();
    const endpoint = endpoints.navigation.authorBooks
      .replace(':lang', lang)
      .replace(':id', authorId.toString());
    return instance.apiService
      .setEndpoint(endpoint)
      .setToken(store.state.auth.token)
      .get()
      .then(response => response.data.data);
  }

  static async getLetterBooks(lang: string, letter: string) {
    const instance = this.getInstance();
    const endpoint = endpoints.navigation.letterBooks.replace(':lang', lang).replace(':letter', letter);
    return instance.apiService
      .setEndpoint(endpoint)
      .setToken(store.state.auth.token)
      .get()
      .then(response => response.data.data);
  }

  static async getBookSections(lang: string, bookId: string) {
    const instance = this.getInstance();
    const endpoint = endpoints.navigation.bookSections.replace(':lang', lang).replace(':id', bookId);
    return instance.apiService
      .setEndpoint(endpoint)
      .setToken(store.state.auth.token)
      .get()
      .then(response => response.data.data);
  }

  static async getBookParams(lang: string, bookSlug: string) {
    const instance = this.getInstance();
    const endpoint = endpoints.navigation.bookParams.replace(':lang', lang).replace(':book', bookSlug);
    return instance.apiService
      .setEndpoint(endpoint)
      .setToken(store.state.auth.token)
      .get()
      .then(response => response.data.data);
  }

  static async filterCategories(lang: string, query: string) {
    const instance = this.getInstance();
    return instance.apiService
      .setEndpoint(endpoints.navigation.filterCategories.replace(':lang', lang))
      .setToken(store.state.auth.token)
      .setBody({ language: lang, query })
      .post()
      .then(response => response.data.data);
  }

  static async filterAuthors(lang: string, query: string) {
    const instance = this.getInstance();
    return instance.apiService
      .setEndpoint(endpoints.navigation.filterAuthors.replace(':lang', lang))
      .setToken(store.state.auth.token)
      .setBody({ language: lang, query })
      .post()
      .then(response => response.data.data);
  }

  static async filterLetters(lang: string, query: string) {
    const instance = this.getInstance();
    return instance.apiService
      .setEndpoint(endpoints.navigation.filterLetters.replace(':lang', lang))
      .setToken(store.state.auth.token)
      .setBody({ language: lang, query })
      .post()
      .then(response => response.data.data);
  }

  static async searchBooks(lang: string, query: string, options: Partial<SearchBaseOptions> = {}) {
    const instance = this.getInstance();
    return instance.apiService
      .setEndpoint(endpoints.navigation.searchBooks.replace(':lang', lang))
      .setToken(store.state.auth.token)
      .setBody({
        language: lang,
        query,
        ...options
      })
      .post()
      .then(response => response.data.data);
  }

  static async searchBookSections(
    lang: string,
    query: string,
    bookSlug: string,
    options: Partial<SearchBaseOptions> = {}
  ) {
    const instance = this.getInstance();
    return instance.apiService
      .setEndpoint(endpoints.navigation.searchBookSections.replace(':lang', lang).replace(':book', bookSlug))
      .setToken(store.state.auth.token)
      .setBody({
        language: lang,
        query,
        ...options
      })
      .post()
      .then(response => response.data.data);
  }

  static async searchBookSectionEntries(
    lang: string,
    query: string,
    bookSlug: string,
    options: Partial<SearchBaseOptions> = {}
  ) {
    const instance = this.getInstance();
    return instance.apiService
      .setEndpoint(
        endpoints.navigation.searchBookSectionEntries.replace(':lang', lang).replace(':book', bookSlug)
      )
      .setToken(store.state.auth.token)
      .setBody({
        language: lang,
        query,
        ...options
      })
      .post()
      .then(response => response.data.data);
  }
}
