export default class ArrayService {
  /**
   * Get intersections between two arrays
   * e.g.:
   * array1 = [1, 2, 3]
   * array2 = [2, 3, 4]
   * should return [2, 3]
   */
  public static getIntersections(array1: Array<string | number>, array2: Array<string | number>) {
    return array1.filter(one => array2.includes(one));
  }

  /**
   * Same as ArrayService.getIntersections, except it returns boolean
   */
  public static hasIntersections(array1: Array<string | number>, array2: Array<string | number>) {
    return ArrayService.getIntersections(array1, array2).length > 0;
  }

  /**
   * Extract IDs, e.g.
   * Array[{ id: 1, a: 2, b: 3 }, { id: 2, a: 7, b: 8 }]
   * will be converted to
   * Array[1, 2]
   */
  public static extractIds(array: Array<{ [key: string]: any; id: number | string }>) {
    return array.map(one => one.id);
  }

  /**
   * Creates hash from IDs of array elements, e.g.
   * Array[{ id: 1, a: 2, b: 3 }, { id: 2, a: 7, b: 8 }]
   * will be converted to
   * 12
   */
  public static makeHashFromIds(array: Array<{ [key: string]: any; id: number | string }>) {
    return JSON.stringify(ArrayService.extractIds(array));
  }
}
