



































































































































import Vue from 'vue';
import Component from 'vue-class-component';
import InputText from '@/components/ui/InputText.vue';
import { Mutation, State } from 'vuex-class';
import { User } from '@/store/modules/user';
import UserService from '@/services/Api/UserService';
import { getTranslation } from '@/services/Translation';
@Component({
  components: { InputText }
})
export default class Profile extends Vue {
  editMode: boolean = false;

  @State('data', { namespace: 'user' })
  user!: User;

  @Mutation('set', { namespace: 'user' })
  setUser!: Function;

  payload: { [fieldName: string]: string } = {};

  errors: { [field: string]: Array<string> } = {};

  getTranslation = getTranslation;

  mounted() {
    this.payload = {};
    Object.entries(this.user)
      .filter(([fieldName]) => fieldName !== 'id')
      .forEach(([fieldName, value]) => {
        this.payload[fieldName] = value;
      });
  }

  async submit() {
    try {
      const payload: { [key: string]: string } = {};
      Object.entries(this.payload)
        .filter(([fieldName, value]) => !!value)
        .forEach(([fieldName, value]) => {
          payload[fieldName] = value;
        });
      const user = await UserService.updateUser(payload);
      this.setUser(user);
      this.editMode = false;
    } catch (e) {
      this.errors = e.response.data.errors;
    }
  }

  async onChangeField(fieldName: string, value: string) {
    this.payload[fieldName] = value;
  }
}
