import { ApiService } from '@/services/Api/ApiService';
import { endpoints } from '@/api-endpoints.json';
import { store } from '@/store';

export default class AuthService {
  static async login(email: string, password: string) {
    const endpoint = endpoints.auth.login;
    return new ApiService()
      .setEndpoint(endpoint)
      .setBody({
        email,
        password
      })
      .post();
  }

  static async logout() {
    const endpoint = endpoints.auth.logout;
    return new ApiService().setEndpoint(endpoint).get();
  }

  static async forgotPassword(email: string) {
    const endpoint = endpoints.auth.forgotPassword;
    return new ApiService()
      .setEndpoint(endpoint)
      .setBody({
        email
      })
      .post();
  }

  static async resetPassword(token: string, email: string, password: string, passwordConfirmation: string) {
    const endpoint = endpoints.auth.resetPassword;
    return new ApiService()
      .setEndpoint(endpoint)
      .setBody({
        token,
        email,
        password,
        password_confirmation: passwordConfirmation
      })
      .post();
  }

  static async register(payload: { [fieldName: string]: string }) {
    const endpoint = endpoints.auth.register;
    return new ApiService()
      .setEndpoint(endpoint)
      .setBody(payload)
      .post();
  }

  static async verifyEmail(userId: string, hash: string, expires: string, signature: string) {
    const endpoint = endpoints.auth.verifyEmail.replace(':userId', userId).replace(':hash', hash);
    return new ApiService()
      .setToken(store.state.auth.token)
      .setEndpoint(endpoint)
      .setParams({ expires, signature })
      .get();
  }

  static async verifyEmailResend() {
    const endpoint = endpoints.auth.verifyEmailResend;
    return new ApiService()
      .setToken(store.state.auth.token)
      .setEndpoint(endpoint)
      .post();
  }
}
