



































import Vue from 'vue';
import Component from 'vue-class-component';
import { Watch } from 'vue-property-decorator';
import { Getter } from 'vuex-class';
import { getTranslation } from '@/services/Translation';
import { Book } from '@/services/Navigation/types';
import BooksService from '@/services/Api/BooksService';
import UrlBuilderService from '@/services/UrlBuilderService';

@Component
export default class BottomBarBookInfo extends Vue {
  bookDetails: any = null;

  @Getter('currentBook', { namespace: 'navigation' })
  currentBook?: Book;

  getTranslation = getTranslation;

  async mounted() {
    await this.fetchBookDetails();
  }

  @Watch('currentBook.id')
  async onChangeBookId() {
    await this.fetchBookDetails();
  }

  async fetchBookDetails() {
    if (this.currentBook) {
      this.bookDetails = await BooksService.getBookCover(this.currentBook.language, this.currentBook.slug);
    }
  }

  getAuthorLink(slug: string) {
    return UrlBuilderService.getAuthorUrl({ language: this.$route.params.language, authorSlug: slug });
  }
}
