import { ActionTree, GetterTree, Module, MutationTree } from 'vuex';
import { RootState } from '@/store';
import SearchService, { SearchItem } from '@/services/Api/SearchService';
import router from '@/router';
import { Book, BookSection, Category } from '@/services/Navigation/types';
import ArrayService from '@/services/ArrayService';
import SearchScopeService from '@/services/SearchScopeService';

export interface SearchState {
  advancedSearch: boolean;
  inBookSearch: boolean;
  results: Array<SearchItem>;
  resultsCount: number;
  priorityResults: null | object;
  needUpdate: boolean;
  loading: boolean;
  error: boolean;
}

const actions: ActionTree<SearchState, RootState> = {
  async fetchResults({ commit, getters, state }, { offset, perPage }) {
    const { language } = router.currentRoute.params;
    const { query } = router.currentRoute.query;
    const searchOptions = getters.searchOptions;
    commit('setError', false);
    if (typeof query === 'string' && query) {
      commit('setLoading', true);
      try {
        const hasSelectedScope = SearchScopeService.hasActiveScope(searchOptions);
        const [searchResults, searchPriorityResults] = await Promise.all([
          SearchService.search(language, query, {
            size: perPage,
            from: offset,
            ...searchOptions
          }),
          hasSelectedScope ? Promise.resolve(null) : SearchService.getPriorityResults(language, query)
        ]);
        let { results } = searchResults.data;
        const { total_results } = searchResults.data;
        if (offset > 0) {
          results = state.results.concat(results);
        }
        commit('setResults', results);
        commit('setResultsCount', total_results);
        commit('setPriorityResults', searchPriorityResults);
      } catch (e) {
        commit('setResults', []);
        commit('setResultsCount', 0);
        commit('setPriorityResults', null);
        commit('setError', true);
      } finally {
        commit('setLoading', false);
      }
    } else {
      commit('setResults', []);
      commit('setResultsCount', 0);
      commit('setPriorityResults', null);
    }
    commit('setNeedUpdate', false);
  }
};

const state: SearchState = {
  advancedSearch: false,
  inBookSearch: false,
  results: [],
  resultsCount: 0,
  priorityResults: null,
  needUpdate: false,
  loading: false,
  error: false
};

const mutations: MutationTree<SearchState> = {
  setResults(state, items) {
    state.results = items;
  },
  setResultsCount(state, resultsCount) {
    state.resultsCount = resultsCount;
  },
  setPriorityResults(state, priorityResults) {
    state.priorityResults = priorityResults;
  },
  setAdvancedSearch(state, advancedSearch) {
    state.advancedSearch = advancedSearch;
  },
  setInBookSearch(state, inBookSearch) {
    state.inBookSearch = inBookSearch;
  },
  setNeedUpdate(state, needUpdated) {
    state.needUpdate = needUpdated;
  },
  setLoading(state, loading) {
    state.loading = loading;
  },
  setError(state, error) {
    state.error = error;
  }
};

const getters: GetterTree<SearchState, RootState> = {
  searchOptions(state: SearchState, getters, rootState, rootGetters) {
    const {
      searchInPoem,
      exact,
      considerDiacritics,
      equalizeWriting,
      slug,
      bookId,
      inBookOnly,
      bookSearch
    } = router.currentRoute.query;
    const { showSearchResultsFlag } = rootState.navigation;
    const checkedBooks = rootGetters['navigation/checkedBooks'] as Array<Book>;
    const checkedCategories = rootGetters['navigation/checkedCategories'] as Array<Category>;
    const checkedBookSections = rootGetters['navigation/checkedBookSections'] as Array<BookSection>;
    const navigationData = rootGetters['navigation/dataFromStateLanguage'] || {};
    const navigationBooks = Object.values(navigationData.books || {}) as Array<Book>;
    const foundBooks = Object.values(navigationData.foundBooks || {}) as Array<Book>;
    const checkedFoundBooks = rootGetters['navigation/checkedFoundBooks'] as Array<Book>;
    const checkedFoundBookSections = rootGetters['navigation/checkedFoundBookSections'] as Array<BookSection>;
    const hasBookSlug = typeof slug === 'string' && !!slug;
    const routeRequestsBookSearch = inBookOnly === '1' || bookSearch === '1';
    const useBookScope = hasBookSlug && (state.inBookSearch || routeRequestsBookSearch);
    const useSelectedScope = state.advancedSearch && !useBookScope;
    const routeBookId = typeof bookId === 'string' ? parseInt(bookId, 10) : NaN;
    const scopedBook = [...navigationBooks, ...foundBooks].find(book => book.slug === slug);
    const scopedBookId = routeBookId > 0 ? routeBookId : scopedBook && scopedBook.id;

    let booksIds: Array<number> = [];
    if (useBookScope && scopedBookId) {
      booksIds = [scopedBookId];
    } else if (useSelectedScope) {
      if (
        showSearchResultsFlag &&
        checkedFoundBooks.length &&
        checkedFoundBooks.length !== foundBooks.length
      ) {
        booksIds = ArrayService.extractIds([...checkedBooks, ...checkedFoundBooks]) as Array<number>;
      } else if (checkedBooks.length) {
        booksIds = ArrayService.extractIds(checkedBooks) as Array<number>;
      }
    }

    return {
      book_slug: useBookScope && typeof slug === 'string' ? slug : '',
      search_in_poem: !!searchInPoem,
      exact: !!exact,
      consider_diacritics: !!considerDiacritics,
      equalize_writing: !!equalizeWriting,
      books: booksIds,
      categories: useSelectedScope ? ArrayService.extractIds(checkedCategories) : [],
      book_sections: useSelectedScope
        ? ArrayService.extractIds(
            checkedFoundBookSections.length ? checkedFoundBookSections : checkedBookSections
          )
        : []
    };
  }
};

export const module = {
  namespaced: true,
  state,
  actions,
  mutations,
  getters
} as Module<SearchState, RootState>;
