import StorageService from '@/services/StorageService';
import { Module, MutationTree } from 'vuex';
import { RootState } from '@/store';

export type BookmarkType = 'manual';

export interface Bookmark {
  id: string | number;
  type: BookmarkType;
  bookKey: string;
  bookName: string;
  language: string;
  book: string;
  link: string;
  location: string;
  position: number;
  anchor?: string;
  note?: string;
  updatedAt: string;
}

export interface BookmarksState {
  list: Array<Bookmark>;
  ownerKey: string;
}

const storageKey = (ownerKey: string) => `bookmarks:${ownerKey}`;

const save = (state: BookmarksState) => {
  StorageService.save(storageKey(state.ownerKey || 'guest'), state.list);
};

const normalize = (records: Array<Bookmark> | null | undefined): Array<Bookmark> =>
  (Array.isArray(records) ? records : [])
    .filter(record => record && record.bookKey && record.link)
    .map(record => ({
      ...record,
      type: 'manual',
      position: Number(record.position) || 0,
      anchor: record.anchor || '',
      note: record.note || '',
      updatedAt: record.updatedAt || ''
    }));

export const mapServerBookmark = (record: any): Bookmark | null => {
  if (!(record && record.language && record.slug)) {
    return null;
  }
  const sectionSlug = record.section_slug || '';
  return {
    id: record.id,
    type: 'manual',
    bookKey: `${record.language}:${record.slug}`,
    bookName: record.name || '',
    language: record.language,
    book: record.slug,
    link: sectionSlug
      ? `/${record.language}/books/${record.slug}/${sectionSlug}`
      : `/${record.language}/books/${record.slug}`,
    location: record.section_name || sectionSlug,
    position: Number(record.scroll_ratio) || 0,
    anchor: record.paragraph_anchor || '',
    note: record.note || '',
    updatedAt: record.updated_at || ''
  };
};

const state: BookmarksState = {
  list: normalize(StorageService.get(storageKey('guest'))),
  ownerKey: 'guest'
};

const mutations: MutationTree<BookmarksState> = {
  switchOwner(state, ownerKey: string) {
    const nextOwnerKey = ownerKey || 'guest';
    if (state.ownerKey === nextOwnerKey) {
      return;
    }
    state.ownerKey = nextOwnerKey;
    state.list = normalize(StorageService.get(storageKey(nextOwnerKey)));
  },
  mergeServerRecords(state, records: Array<any>) {
    if (!Array.isArray(records)) {
      return;
    }
    const localBookmarks = state.list.filter(item => String(item.id).startsWith('local:'));
    const serverBookmarks = records.map(mapServerBookmark).filter(Boolean) as Array<Bookmark>;
    state.list = [...localBookmarks, ...serverBookmarks];
    state.list.sort((left, right) => right.updatedAt.localeCompare(left.updatedAt));
    save(state);
  },
  upsert(state, bookmark: Bookmark) {
    const normalized = normalize([bookmark])[0];
    if (!normalized) {
      return;
    }
    const index = state.list.findIndex(item => String(item.id) === String(normalized.id));
    if (index >= 0) {
      state.list.splice(index, 1, normalized);
    } else {
      state.list.unshift(normalized);
    }
    state.list.sort((left, right) => right.updatedAt.localeCompare(left.updatedAt));
    save(state);
  },
  remove(state, id: string | number) {
    state.list = state.list.filter(item => String(item.id) !== String(id));
    save(state);
  }
};

export const module = {
  namespaced: true,
  state,
  mutations
} as Module<BookmarksState, RootState>;
