




import Vue from 'vue';
import { State } from 'vuex-class';
import Component from 'vue-class-component';
import { Watch } from 'vue-property-decorator';
import { getTranslation } from '@/services/Translation';
import HelpService from '@/services/Api/HelpService';

@Component
export default class Help extends Vue {
  content = '';

  @State('interfaceLanguage', { namespace: 'reader' })
  interfaceLanguage!: string;

  async mounted() {
    await this.actualizeContent();
  }

  @Watch('interfaceLanguage')
  async onInterfaceLanguageChange() {
    await this.actualizeContent();
  }

  async actualizeContent() {
    this.$store.commit('tabs/updateActiveTabName', getTranslation('help'));
    const { html } = await HelpService.getHelp(this.interfaceLanguage);
    this.content = html;
  }
}
