























































































import Vue from 'vue';
import AuthLayout from '@/layouts/AuthLayout.vue';
import AuthService from '@/services/Api/AuthService';
import Component from 'vue-class-component';
import InputText from '@/components/ui/InputText.vue';
import { getTranslation } from '@/services/Translation';

@Component({
  components: { AuthLayout, InputText }
})
export default class ResetPassword extends Vue {
  loading = false;
  registered = false;
  error = '';
  errors: { [field: string]: Array<string> } = {};
  payload: { [fieldName: string]: string } = {
    email: '',
    name: '',
    last_name: '',
    password: '',
    spiritual_name: '',
    access_code: ''
  };
  getTranslation = getTranslation;

  async submit() {
    if (this.loading) {
      return;
    }
    this.loading = true;
    try {
      this.payload.password_confirmation = this.payload.password;
      await AuthService.register(this.payload);
      this.registered = true;
    } catch (e) {
      this.error =
        e.response && e.response.data && e.response.data.message
          ? e.response.data.message
          : e.message || getTranslation('defaultErrorMessage');

      this.errors = e.response.data.errors;
    } finally {
      this.loading = false;
    }
  }

  async onChangeField(fieldName: string, value: string) {
    this.payload[fieldName] = value;
  }
}
