




















import Vue from 'vue';
import NewsService from '@/services/Api/NewsService';
import UserService from '@/services/Api/UserService';
import NewsList from '@/components/NewsList.vue';
import UserRecentBooks from '@/components/UserRecentBooks.vue';
import SearchHistory from '@/components/SearchHistory.vue';
import Component from 'vue-class-component';
import { getTranslation } from '@/services/Translation';
import { State } from 'vuex-class';
import { Watch } from 'vue-property-decorator';

@Component({
  components: { NewsList, UserRecentBooks, SearchHistory }
})
export default class Home extends Vue {
  tabs = [
    {
      code: 'news',
      name: getTranslation('news')
    },
    {
      code: 'recently-viewed-books',
      name: getTranslation('recentlyViewedBooks')
    },
    {
      code: 'search-history',
      name: getTranslation('searchQueries')
    }
  ];

  currentTab: string = 'news';
  news: Array<any> = [];
  userRecentBooks: Array<any> = [];
  pagination = {
    current: 1,
    total: 1
  };

  @State('interfaceLanguage', { namespace: 'reader' })
  interfaceLanguage!: string;

  async mounted() {
    this.$store.commit('tabs/updateActiveTabName', 'Vedarama');
    await this.fetchNews();
    await this.fetchUserRecentBooks();
  }

  @Watch('interfaceLanguage')
  async onChangeInterfaceLang() {
    this.tabs = [
      {
        code: 'news',
        name: getTranslation('news')
      },
      {
        code: 'recently-viewed-books',
        name: getTranslation('recentlyViewedBooks')
      },
      {
        code: 'search-history',
        name: getTranslation('searchQueries')
      }
    ];
    await this.fetchNews();
  }

  async fetchNews() {
    const { data, pagination } = await NewsService.getNews();
    this.news = data;
    if (pagination) {
      this.pagination = pagination;
    }
  }

  async fetchUserRecentBooks() {
    this.userRecentBooks = await UserService.getUserRecentBooks();
  }
}
