import StorageService from '@/services/StorageService';
import { Module, MutationTree } from 'vuex';
import { RootState } from '@/store';

export interface Tab {
  name: string;
  link: null | string;
  active: boolean;
  bookKey?: null | string;
  bookName?: string;
  location?: string;
  position?: number;
  paragraphAnchor?: string;
  updatedAt?: string;
  sectionPositions?: { [link: string]: number };
}

export type TabsState = {
  list: Array<Tab>;
  closed?: { [bookKey: string]: Tab };
  ownerKey?: string;
};

const emptyTab = {
  name: '',
  link: null,
  active: true,
  bookKey: null,
  bookName: '',
  location: '',
  position: 0,
  paragraphAnchor: '',
  updatedAt: '',
  sectionPositions: {}
};

const tabsStorageKey = (ownerKey: string) => `tabs:${ownerKey}`;
const closedTabsStorageKey = (ownerKey: string) => `closedTabs:${ownerKey}`;

const saveTabs = (state: TabsState) => {
  StorageService.save(tabsStorageKey(state.ownerKey || 'guest'), state.list);
};

const saveClosedTabs = (state: TabsState) => {
  StorageService.save(closedTabsStorageKey(state.ownerKey || 'guest'), state.closed || {});
};

export const getBookKeyFromLink = (link?: null | string): string | null => {
  if (!link) {
    return null;
  }
  const segments = link
    .split('?')[0]
    .split('/')
    .filter(Boolean);
  if (segments.length >= 3 && segments[1] === 'books') {
    return `${segments[0]}:${segments[2]}`;
  }
  if (segments.length >= 4 && ['categories', 'authors'].includes(segments[1])) {
    return `${segments[0]}:${segments[3]}`;
  }
  return null;
};

export const isBookSectionLink = (link?: null | string): boolean => {
  if (!link) {
    return false;
  }
  const segments = link
    .split('?')[0]
    .split('/')
    .filter(Boolean);
  if (segments[1] === 'books') {
    return segments.length >= 4;
  }
  return ['categories', 'authors'].includes(segments[1]) && segments.length >= 5;
};

const getLegacyBookDetails = (tab: Tab, bookKey: string | null) => {
  if (!bookKey) {
    return { bookName: tab.bookName || '', location: tab.location || '' };
  }
  const parts = (tab.name || '').split(' — ');
  return {
    bookName: tab.bookName || parts[0] || '',
    location: tab.location || (parts.length > 1 ? parts.slice(1).join(' — ') : '')
  };
};

export const normalizeTabs = (tabs: Array<Tab> | null | undefined): Array<Tab> => {
  const normalized = Array.isArray(tabs)
    ? tabs
        .filter(tab => tab && typeof tab === 'object')
        .map(tab => {
          const link = tab.link || null;
          const bookKey = tab.bookKey || getBookKeyFromLink(link);
          return {
            name: tab.name || '',
            link,
            active: !!tab.active,
            bookKey,
            position: typeof tab.position === 'number' ? tab.position : 0,
            paragraphAnchor: tab.paragraphAnchor || '',
            updatedAt: tab.updatedAt || '',
            sectionPositions: tab.sectionPositions || {},
            ...getLegacyBookDetails(tab, bookKey)
          };
        })
    : [];
  if (!normalized.length) {
    return [{ ...emptyTab }];
  }
  let activeIndex = -1;
  normalized.forEach((tab, index) => {
    if (tab.active) {
      activeIndex = index;
    }
  });
  if (activeIndex < 0) {
    activeIndex = 0;
  }
  return normalized.map((tab, index) => ({ ...tab, active: index === activeIndex }));
};

const state: TabsState = {
  list: normalizeTabs(StorageService.get(tabsStorageKey('guest'))),
  closed: StorageService.get(closedTabsStorageKey('guest')) || {},
  ownerKey: 'guest'
};

const mutations: MutationTree<TabsState> = {
  switchOwner(state: TabsState, ownerKey: string) {
    const nextOwnerKey = ownerKey || 'guest';
    if (state.ownerKey === nextOwnerKey) {
      return;
    }
    state.ownerKey = nextOwnerKey;
    state.list = normalizeTabs(StorageService.get(tabsStorageKey(nextOwnerKey)));
    state.closed = StorageService.get(closedTabsStorageKey(nextOwnerKey)) || {};
  },
  openTab(state: TabsState) {
    state.list.map(tab => Object.assign(tab, { active: false }));
    state.list.push({ ...emptyTab });
    saveTabs(state);
  },
  closeTab(state, index) {
    if (!state.list[index]) {
      return;
    }
    const closingTab = state.list[index];
    const wasActive = closingTab.active;
    if (closingTab.bookKey) {
      state.closed = state.closed || {};
      state.closed[closingTab.bookKey] = { ...closingTab, active: false };
      saveClosedTabs(state);
    }
    state.list.splice(index, 1);
    if (state.list.length === 0) {
      state.list.push({ ...emptyTab });
    } else if (wasActive) {
      state.list[Math.min(index, state.list.length - 1)].active = true;
    }
    saveTabs(state);
  },
  setActiveTab(state, index) {
    if (!state.list[index]) {
      return;
    }
    state.list.map(tab => Object.assign(tab, { active: false }));
    state.list[index].active = true;
    saveTabs(state);
  },
  keepOnlyActiveTab(state) {
    const activeTab = state.list.find(tab => tab.active);
    if (!activeTab) {
      return;
    }
    state.closed = state.closed || {};
    state.list.forEach(tab => {
      if (tab !== activeTab && tab.bookKey) {
        state.closed![tab.bookKey] = { ...tab, active: false };
      }
    });
    state.list = [activeTab];
    saveClosedTabs(state);
    saveTabs(state);
  },
  activateBookTab(state, payload) {
    state.closed = state.closed || {};
    const existingIndex = state.list.findIndex(tab => tab.bookKey === payload.bookKey);
    const activeEmptyIndex = state.list.findIndex(tab => tab.active && !tab.link);
    const targetIndex =
      existingIndex >= 0 ? existingIndex : activeEmptyIndex >= 0 ? activeEmptyIndex : state.list.length;
    const existingTab =
      (existingIndex >= 0 ? state.list[existingIndex] : state.closed[payload.bookKey]) ||
      state.list[targetIndex];
    const keepSavedSection =
      !!payload.preserveLastLocation && !!existingTab && isBookSectionLink(existingTab.link);
    const bookName =
      payload.bookName ||
      (existingTab && existingTab.bookName) ||
      (existingTab && existingTab.name) ||
      (payload.location === undefined ? payload.name : '') ||
      '';
    const location =
      payload.location !== undefined
        ? payload.location
        : existingTab && existingTab.location
        ? existingTab.location
        : '';
    const keepExistingPosition =
      keepSavedSection ||
      (!!existingTab && existingTab.link === payload.link && payload.position === undefined);
    const savedSectionPosition =
      existingTab &&
      existingTab.sectionPositions &&
      typeof existingTab.sectionPositions[payload.link] === 'number'
        ? existingTab.sectionPositions[payload.link]
        : 0;
    const position =
      payload.position !== undefined
        ? payload.position
        : keepExistingPosition && existingTab && typeof existingTab.position === 'number'
        ? existingTab.position
        : savedSectionPosition;
    const tab: Tab = {
      name: payload.name || (existingTab && existingTab.name) || bookName,
      link: keepSavedSection ? existingTab.link : payload.link,
      active: true,
      bookKey: payload.bookKey,
      bookName,
      location,
      position,
      paragraphAnchor:
        payload.paragraphAnchor !== undefined
          ? payload.paragraphAnchor
          : keepExistingPosition && existingTab
          ? existingTab.paragraphAnchor || ''
          : '',
      updatedAt: payload.updatedAt || (existingTab && existingTab.updatedAt) || '',
      sectionPositions: (existingTab && existingTab.sectionPositions) || {}
    };

    state.list.forEach(item => {
      item.active = false;
    });
    if (existingTab) {
      if (targetIndex < state.list.length) {
        state.list.splice(targetIndex, 1, tab);
      } else {
        state.list.push(tab);
      }
    } else {
      state.list.push(tab);
    }
    if (state.closed[payload.bookKey]) {
      delete state.closed[payload.bookKey];
      saveClosedTabs(state);
    }
    saveTabs(state);
  },
  activateRouteTab(state, payload) {
    const activeIndex = state.list.findIndex(tab => tab.active);
    const activeTab = state.list[activeIndex];
    if (activeTab && activeTab.bookKey) {
      const routeTabIndex = state.list.findIndex(tab => !tab.bookKey && tab.link === payload.link);
      state.list.forEach(tab => {
        tab.active = false;
      });
      if (routeTabIndex >= 0) {
        state.list[routeTabIndex].active = true;
      } else {
        state.list.push({
          ...emptyTab,
          name: payload.name || '',
          link: payload.link
        });
      }
    } else if (activeTab) {
      activeTab.link = payload.link;
      if (payload.name) {
        activeTab.name = payload.name;
      }
    }
    saveTabs(state);
  },
  updateActiveTabLink(state, link) {
    const index = state.list.findIndex(tab => tab.active);
    if (index < 0) {
      return;
    }
    state.list[index].link = link;
    saveTabs(state);
  },
  updateActiveTabName(state, name) {
    const index = state.list.findIndex(tab => tab.active);
    if (index < 0) {
      return;
    }
    state.list[index].name = name;
    saveTabs(state);
  },
  updateActiveTabDetails(state, details) {
    const tab = state.list.find(item => item.active);
    if (!tab) {
      return;
    }
    if (details.name !== undefined) {
      tab.name = details.name;
    }
    if (details.bookName !== undefined) {
      tab.bookName = details.bookName;
    }
    if (details.location !== undefined) {
      tab.location = details.location;
    }
    if (details.link !== undefined) {
      tab.link = details.link;
    }
    if (details.position !== undefined) {
      tab.position = details.position;
    }
    if (details.paragraphAnchor !== undefined) {
      tab.paragraphAnchor = details.paragraphAnchor;
    }
    if (details.updatedAt !== undefined) {
      tab.updatedAt = details.updatedAt;
    }
    saveTabs(state);
  },
  updateBookTabDetails(state, payload) {
    const tab = state.list.find(item => item.bookKey === payload.bookKey);
    if (!tab) {
      return;
    }
    Object.assign(tab, payload.details);
    if (
      payload.details.link &&
      typeof payload.details.position === 'number' &&
      isBookSectionLink(payload.details.link)
    ) {
      tab.sectionPositions = tab.sectionPositions || {};
      tab.sectionPositions[payload.details.link] = payload.details.position;
    }
    saveTabs(state);
  },
  mergeServerReadingTabs(state, records) {
    if (!Array.isArray(records)) {
      return;
    }
    records.forEach(record => {
      if (!(record && record.language && record.slug)) {
        return;
      }
      const bookKey = `${record.language}:${record.slug}`;
      if (state.closed && state.closed[bookKey]) {
        return;
      }
      const sectionSlug = record.section_slug || '';
      const link = sectionSlug
        ? `/${record.language}/books/${record.slug}/${sectionSlug}`
        : `/${record.language}/books/${record.slug}`;
      const serverUpdatedAt = record.updated_at || '';
      const existing = state.list.find(tab => tab.bookKey === bookKey);
      const serverIsNewer =
        !existing || !existing.updatedAt || !serverUpdatedAt || serverUpdatedAt >= existing.updatedAt;
      const serverClearedStaleSection = !!existing && !sectionSlug && isBookSectionLink(existing.link);
      if (existing && (serverIsNewer || serverClearedStaleSection)) {
        existing.name = record.name || existing.name;
        existing.bookName = record.name || existing.bookName;
        existing.link = link;
        existing.location = record.section_name || sectionSlug;
        existing.position = Number(record.scroll_ratio) || 0;
        existing.updatedAt = serverUpdatedAt;
        existing.sectionPositions = {
          ...(existing.sectionPositions || {}),
          ...(record.section_positions || {})
        };
      } else if (!existing) {
        state.list.push({
          name: record.name || '',
          link,
          active: false,
          bookKey,
          bookName: record.name || '',
          location: record.section_name || sectionSlug,
          position: Number(record.scroll_ratio) || 0,
          updatedAt: serverUpdatedAt,
          sectionPositions: record.section_positions || {}
        });
      }
    });
    saveTabs(state);
  }
};

export const module = {
  namespaced: true,
  state,
  mutations
} as Module<TabsState, RootState>;
