






























import Vue from 'vue';
import Component from 'vue-class-component';
import { Mutation } from 'vuex-class';
import { LANGUAGE_CODE_ENGLISH, LANGUAGE_CODE_RUSSIAN, LANGUAGE_CODE_SANSKRIT, LANGUAGES } from '@/constants';
import IconStar from '@/assets/icons/star.svg';
import IconBookmark from '@/assets/icons/bookmark.svg';
import IconSettings from '@/assets/icons/settings.svg';
import IconHelp from '@/assets/icons/help.svg';
import IconCatalogRu from '@/assets/icons/catalog-ru.svg';
import IconCatalogEn from '@/assets/icons/catalog-en.svg';
import IconCatalogSt from '@/assets/icons/catalog-st.svg';
import { getTranslation } from '@/services/Translation';

@Component({
  components: {
    IconStar,
    IconBookmark,
    IconSettings,
    IconHelp
  }
})
export default class Sidebar extends Vue {
  @Mutation('setReadMode', { namespace: 'reader' })
  setReadMode!: Function;

  @Mutation('setLanguage', { namespace: 'navigation' })
  setLanguage!: Function;

  @Mutation('toggle', { namespace: 'settings' })
  toggleSettings!: Function;

  get languages() {
    return LANGUAGES.map(code => {
      let icon;
      switch (code) {
        case LANGUAGE_CODE_RUSSIAN:
          icon = IconCatalogRu;
          break;
        case LANGUAGE_CODE_ENGLISH:
          icon = IconCatalogEn;
          break;
        case LANGUAGE_CODE_SANSKRIT:
          icon = IconCatalogSt;
          break;
      }
      return { code, icon };
    });
  }

  updateLanguage(language: string) {
    this.setReadMode(false);
    this.setLanguage(language);
  }

  openHelp() {
    this.$store.commit('tabs/openTab');
    this.$store.commit('tabs/updateActiveTabLink', '/help');
    this.$store.commit('tabs/updateActiveTabName', getTranslation('help'));
    this.$router.push('/help');
  }
}
